\begin{proposition}[Scalar-curvature evolution]
\dcref{ch2:5.4}
\label{topping:ricci-flow-scalar-evolution}
\source{topping:page-0043}
\group{topping-background}

Under Ricci flow,
\[
\frac{\partial R}{\partial t}=\Delta R+2|\Ric|^2.
\]
\end{proposition}

